<script setup lang="ts">
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleDataTable from '@orangezh1/qisvc-console-ui/components/ConsoleDataTable'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import ConsoleActionConfirmationDialog from '@orangezh1/qisvc-console-ui/components/ConsoleActionConfirmationDialog'
import AdminConsole from '../../components/console/AdminConsole.vue'
import {dateTime} from '../../utils/update-center'
definePageMeta({layout:'admin'})
type Backup={id:string;source:'manual'|'update'|'pre_restore'|'legacy';actorName:string;version:string|null;taskId:string|null;createdAt:string;finishedAt:string|null;deleteBlocked:string|null;status:'running'|'completed'|'failed'|'legacy'|'deleting';stage:string|null;bytes:number|null;sha256:string|null;verification:string;verifiedAt:string|null;error:string|null}
type Listing={ready:boolean;message:string;automaticBeforeUpdate:boolean;running:boolean;total:number;items:Backup[]}
const auth=useApi(),toast=useToast(),config=useRuntimeConfig(),session=await auth.restore()
if(!session)await navigateTo('/admin/login',{replace:true})
else if(session.role!=='root'||!session.permissions.includes('backups.read'))throw createError({statusCode:403,statusMessage:'没有数据安全访问权限'})
const page=ref(1),pageSize=ref(20),error=ref(''),active=ref<string|null>(null),listBusy=ref(false),listAction=ref('refresh'),createOpen=ref(false),creationError=ref(''),requestId=ref(''),detail=ref<Backup|null>(null),detailOpen=ref(false),ownJob=ref('')
const canCreate=!!session?.permissions.includes('backups.create'),canDownload=!!session?.permissions.includes('backups.download')
const params=()=>new URLSearchParams({page:String(page.value),pageSize:String(pageSize.value)})
const initial=await useAsyncData('data-security-backups',()=>auth.api<Listing>('/admin/backups?'+params()))
const data=ref<Listing>(initial.data.value??{ready:false,message:'备份服务读取失败',automaticBeforeUpdate:false,running:false,total:0,items:[]});if(initial.error.value)error.value='备份记录读取失败，请重试'
const columns=[{id:'select',header:''},{id:'created',header:'备份时间'},{id:'source',header:'来源'},{id:'status',header:'状态'},{id:'size',header:'文件大小'},{id:'verification',header:'完整性'},{id:'actions',header:'操作'}]
const canDelete=!!session?.permissions.includes('backups.delete'),canRestore=!!session?.permissions.includes('backups.restore')
const selected=ref<string[]>([]),deleteRows=ref<Backup[]>([]),deleteOpen=ref(false),deleteError=ref(''),deleteOrigin=ref('batch')
const selectable=computed(()=>data.value.items.filter(r=>!r.deleteBlocked))
const allSelected=computed(()=>selectable.value.length>0&&selectable.value.every(r=>selected.value.includes(r.id)))
function selectRow(id:string,checked:boolean|'indeterminate'){selected.value=checked===true?[...new Set([...selected.value,id])]:selected.value.filter(v=>v!==id)}
function askDelete(rows:Backup[],origin:string){deleteRows.value=rows;deleteOrigin.value=origin;deleteError.value='';deleteOpen.value=true}
async function remove(){if(active.value)return;active.value='delete:'+deleteOrigin.value;deleteError.value='';try{const result=await auth.api<{deleted:number;failed:number;results:{id:string;deleted:boolean;message?:string}[]}>('/admin/backups/delete','POST',{ids:deleteRows.value.map(r=>r.id),confirm:'永久删除备份'});selected.value=selected.value.filter(id=>!result.results.some(r=>r.id===id&&r.deleted));if(result.failed)deleteError.value=result.results.filter(r=>!r.deleted).map(r=>r.message).join('；');else deleteOpen.value=false;toast.add({title:`已删除 ${result.deleted} 份备份${result.failed?'，'+result.failed+' 份未删除':''}`,color:result.failed?'warning':'success'});await load('mutation')}catch(e){deleteError.value=e instanceof Error?e.message:'删除失败'}finally{active.value=null}}
type RestoreStatus={id:string;status:string;stage:string;message:string;token?:string}
const restoreOpen=ref(false),restoreRow=ref<Backup|null>(null),restorePlan=ref<{token:string}|null>(null),restoreConfirm=ref(''),restoreError=ref(''),restoreStatus=ref<RestoreStatus|null>(null),restorePolling=ref(false)
async function askRestore(row:Backup){if(active.value)return;restoreRow.value=row;restoreOpen.value=true;restorePlan.value=null;restoreStatus.value=null;restoreConfirm.value='';restoreError.value='';active.value='preview:'+row.id;try{restorePlan.value=await auth.api('/admin/backups/'+row.id+'/restore-preview','POST',{requestId:crypto.randomUUID()})}catch(e){restoreError.value=e instanceof Error?e.message:'还原检查失败'}finally{active.value=null}}
async function restoreDatabase(){if(active.value||!restorePlan.value)return;active.value='restore';try{restoreStatus.value=await auth.api('/admin/backups/restore','POST',{token:restorePlan.value.token,confirm:restoreConfirm.value});await pollRestore()}catch(e){restoreError.value=e instanceof Error?e.message:'还原请求失败';active.value=null}}
async function pollRestore(){if(restorePolling.value||!restoreStatus.value?.token)return;restorePolling.value=true;try{const value=await auth.api<RestoreStatus>('/admin/backups/restore/status','POST',{id:restoreStatus.value.id,token:restoreStatus.value.token});restoreStatus.value={...restoreStatus.value,...value};restoreError.value='';if(value.status!=='running'){active.value=null;if(value.status==='completed'||value.status==='rolled_back')auth.session.value=null;else if(value.status==='failed')await load('mutation')}}catch(e){restoreError.value='状态暂时读取失败，将自动重试，请勿重复还原'}finally{restorePolling.value=false}}
const sourceName=(r:Backup)=>r.source==='pre_restore'?'还原前保护':r.source==='update'?'更新前备份':r.source==='manual'?'手动备份':'历史备份'
const statusName=(r:Backup)=>r.status==='deleting'?'删除未完成':r.status==='completed'?'已完成':r.status==='failed'?'失败':r.status==='legacy'?'旧格式':({checking:'检查中',dumping:'备份中',verifying:'校验中'} as Record<string,string>)[r.stage||'']||'处理中'
const size=(value:number|null)=>value===null?'—':value<1024**2?(value/1024).toFixed(1)+' KB':(value/1024**2).toFixed(1)+' MB'
let sequence=0,disposed=false,timer:ReturnType<typeof setInterval>|undefined
async function load(source='refresh'){const n=++sequence;listBusy.value=true;listAction.value=source;try{const next=await auth.api<Listing>('/admin/backups?'+params());if(disposed||n!==sequence)return;data.value=next;selected.value=selected.value.filter(id=>next.items.some(r=>r.id===id&&!r.deleteBlocked));error.value='';const job=next.items.find(r=>r.id===ownJob.value);if(job&&job.status!=='running'){toast.add({title:job.status==='completed'?'备份完成，完整性校验通过':'备份未完成',description:job.error||undefined,color:job.status==='completed'?'success':'error'});ownJob.value=''}}catch(e){if(!disposed&&n===sequence)error.value=e instanceof Error?e.message:'读取失败'}finally{if(!disposed&&n===sequence)listBusy.value=false}}
function askCreate(){requestId.value=crypto.randomUUID();creationError.value='';createOpen.value=true}
async function create(){if(active.value)return;active.value='create';creationError.value='';try{const job=await auth.api<Backup>('/admin/backups','POST',{requestId:requestId.value});createOpen.value=false;ownJob.value=job.id;page.value=1;await load('mutation')}catch(e){creationError.value=e instanceof Error?e.message:'创建备份失败'}finally{active.value=null}}
async function verify(row:Backup){if(active.value)return;active.value='verify:'+row.id;try{await auth.api('/admin/backups/'+row.id+'/verify','POST',{});toast.add({title:'备份完整性校验通过',color:'success'});await load('mutation')}catch(e){toast.add({title:e instanceof Error?e.message:'校验失败',color:'error'});await load('mutation')}finally{active.value=null}}
async function download(row:Backup){if(active.value)return;active.value='download:'+row.id;try{await auth.api('/admin/backups/'+row.id+'/prepare-download','POST',{});const a=document.createElement('a');a.href=String(config.public.apiBase).replace(/\/$/,'')+'/admin/backups/'+encodeURIComponent(row.id)+'/download';a.download=row.id+'.zbackup';document.body.appendChild(a);a.click();a.remove();toast.add({title:'已交给浏览器下载加密备份',color:'success'})}catch(e){toast.add({title:e instanceof Error?e.message:'备份下载未开始',color:'error'});await load('mutation')}finally{active.value=null}}
onMounted(()=>{timer=setInterval(()=>{if(restoreStatus.value?.status==='running'){void pollRestore();return}if(document.visibilityState==='visible'&&data.value.running&&!active.value&&!listBusy.value)void load('poll')},1500)})
onBeforeUnmount(()=>{disposed=true;sequence++;if(timer)clearInterval(timer)})
</script>
<template><AdminConsole :refreshing="listBusy&&listAction==='refresh'" @refresh="load('refresh')"><div class="space-y-5">
  <ConsolePageHeading title="数据安全"><template #actions><UButton v-if="canDelete" icon="i-lucide-trash-2" color="error" variant="outline" :disabled="!selected.length||!!active" :loading="active==='delete:batch'" @click="askDelete(data.items.filter(r=>selected.includes(r.id)),'batch')">批量删除<span v-if="selected.length">（{{selected.length}}）</span></UButton><UButton v-if="canCreate" icon="i-lucide-plus" :disabled="!data.ready||data.running||!!active" @click="askCreate">新建备份</UButton></template></ConsolePageHeading>
  <div class="flex flex-wrap items-center gap-x-5 gap-y-2 text-sm text-muted"><span class="inline-flex items-center gap-2"><UIcon name="i-lucide-shield-check" class="size-4 text-primary"/>备份加密保存</span><span class="inline-flex items-center gap-2"><UIcon name="i-lucide-refresh-cw" class="size-4 text-primary"/>{{data.automaticBeforeUpdate?'更新前自动备份数据库已接入':'更新前数据库备份当前不可用，禁止继续更新'}}</span></div>

  <UAlert v-if="!data.ready" :title="data.message" color="warning" variant="subtle"/>
  <ConsoleDataTable :data="data.items" :columns="columns" :error="error" :page="page" :page-size="pageSize" :total="data.total" :client-pagination="false" empty-title="暂无数据库备份" empty-description="手动创建的备份和更新前自动生成的备份将在这里显示。" @retry="load('retry')" @update:page="page=$event;load('page')" @update:page-size="pageSize=$event;page=1;load('page')">
    <template #select-header><UCheckbox v-if="canDelete" aria-label="选择本页可删除的备份" :model-value="allSelected" :disabled="!!active||!selectable.length" @update:model-value="selected=$event===true?selectable.map(r=>r.id):[]"/></template>
    <template #select-cell="{row}"><UCheckbox v-if="canDelete" :aria-label="'选择备份 '+dateTime(row.original.createdAt)" :model-value="selected.includes(row.original.id)" :disabled="!!active||!!row.original.deleteBlocked" :title="row.original.deleteBlocked||''" @update:model-value="selectRow(row.original.id,$event)"/></template>
    <template #created-cell="{row}"><p>{{dateTime(row.original.createdAt)}}</p><p class="mt-1 text-xs text-muted">{{row.original.actorName}}</p></template>
    <template #source-cell="{row}"><UBadge :color="row.original.source==='update'?'primary':'neutral'" variant="subtle">{{sourceName(row.original)}}</UBadge></template>
    <template #status-cell="{row}"><UBadge :color="row.original.status==='completed'?'success':row.original.status==='failed'?'error':'neutral'" variant="subtle">{{statusName(row.original)}}</UBadge></template>
    <template #size-cell="{row}">{{size(row.original.bytes)}}</template>
    <template #verification-cell="{row}"><span :class="row.original.verification==='passed'?'text-success':row.original.verification==='failed'?'text-error':'text-muted'">{{row.original.verification==='passed'?'已验证':row.original.verification==='failed'?'未通过':row.original.status==='running'?'待完成':'未验证'}}</span></template>
    <template #actions-cell="{row}"><UButton class="px-0" size="sm" variant="link" @click="detail=row.original;detailOpen=true">详情</UButton><UButton v-if="row.original.status==='completed'" class="px-0" size="sm" variant="link" :loading="active==='verify:'+row.original.id" :disabled="!!active" @click="verify(row.original)">校验</UButton><UButton v-if="canDownload&&row.original.status==='completed'" class="px-0" size="sm" variant="link" :loading="active==='download:'+row.original.id" :disabled="!!active||row.original.verification==='failed'" @click="download(row.original)">下载</UButton><UButton v-if="canRestore&&row.original.status==='completed'" class="px-0" size="sm" variant="link" :loading="active==='preview:'+row.original.id" :disabled="!!active||row.original.verification==='failed'" @click="askRestore(row.original)">还原</UButton><UButton v-if="canDelete" class="px-0" size="sm" variant="link" color="error" :title="row.original.deleteBlocked||''" :loading="active==='delete:'+row.original.id" :disabled="!!active||!!row.original.deleteBlocked" @click="askDelete([row.original],row.original.id)">{{row.original.deleteBlocked?'受保护':'删除'}}</UButton></template>
  </ConsoleDataTable>
  <UModal v-model:open="deleteOpen" :title="deleteRows.length>1?'批量删除备份':'删除备份'" description="加密备份文件将永久删除，无法恢复。现有数据库不会被删除，操作记录保留。" :dismissible="!active" :close="!active" :ui="{content:'sm:max-w-lg'}"><template #body><div class="space-y-4"><p class="text-sm">确认删除所选 {{deleteRows.length}} 份备份？</p><ul class="max-h-48 overflow-y-auto space-y-2 text-sm text-muted"><li v-for="row in deleteRows" :key="row.id">{{dateTime(row.createdAt)}} · {{sourceName(row)}}</li></ul><UAlert v-if="deleteError" :title="deleteError" color="error"/></div></template><template #footer><ConsoleFormActions class="w-full"><UButton color="neutral" variant="outline" :disabled="!!active" @click="deleteOpen=false">取消</UButton><UButton color="error" :loading="active?.startsWith('delete:')" @click="remove">永久删除</UButton></ConsoleFormActions></template></UModal>
  <UModal v-model:open="restoreOpen" title="还原数据库" description="还原会覆盖备份之后的数据库变更，完成后所有用户需要重新登录。" :dismissible="!active" :close="!active" :ui="{content:'sm:max-w-lg'}"><template #body><div class="space-y-4 text-sm"><p v-if="restoreRow">目标备份：{{dateTime(restoreRow.createdAt)}} · {{restoreRow.version}}</p><UAlert title="还原前会自动创建并校验当前数据库的保护备份，失败即停止。附件、图片和独立密钥不会随数据库还原。" color="warning" variant="subtle"/><p v-if="active?.startsWith('preview:')" class="text-muted">正在校验备份、版本与恢复权限…</p><template v-if="restorePlan&&!restoreStatus"><p class="text-success">兼容性检查通过</p><UFormField label="请输入“确认还原数据库”"><UInput v-model="restoreConfirm" class="w-full" :disabled="!!active" placeholder="确认还原数据库" autocomplete="off"/></UFormField></template><UAlert v-if="restoreStatus" :title="restoreStatus.message" :icon="restoreStatus.status==='running'?'i-lucide-loader-circle':'i-lucide-info'" :color="restoreStatus.status==='completed'?'success':'warning'"/><UAlert v-if="restoreError" :title="restoreError" color="error"/></div></template><template #footer><ConsoleFormActions class="w-full"><UButton v-if="restoreStatus&&['completed','rolled_back'].includes(restoreStatus.status)" to="/admin/login">重新登录</UButton><template v-else><UButton color="neutral" variant="outline" :disabled="!!active" @click="restoreOpen=false">关闭</UButton><UButton v-if="!restoreStatus" color="error" :disabled="!restorePlan||restoreConfirm!=='确认还原数据库'||!!active" :loading="active==='restore'" @click="restoreDatabase">开始还原</UButton><UButton v-else-if="restoreStatus.status==='running'" loading disabled>正在还原</UButton></template></ConsoleFormActions></template></UModal>
  <ConsoleActionConfirmationDialog v-model:open="createOpen" title="创建数据库备份？" :description="creationError||'备份将加密保存，包含当前数据库。文件存储和独立密钥不包含在内，请单独安全保管；本操作不会恢复或覆盖现有数据。'" confirm-label="开始备份" color="primary" :loading="active==='create'" @confirm="create"/>
  <UModal v-model:open="detailOpen" title="备份详情" description="查看备份状态和完整性信息。" :ui="{content:'sm:max-w-xl'}"><template #body><div v-if="detail" class="space-y-5 text-sm"><dl class="grid gap-4 sm:grid-cols-2"><div><dt class="text-muted">备份时间</dt><dd class="mt-1">{{dateTime(detail.createdAt)}}</dd></div><div><dt class="text-muted">完成时间</dt><dd class="mt-1">{{dateTime(detail.finishedAt)}}</dd></div><div><dt class="text-muted">备份来源</dt><dd class="mt-1">{{sourceName(detail)}}</dd></div><div><dt class="text-muted">文件大小</dt><dd class="mt-1">{{size(detail.bytes)}}</dd></div><div><dt class="text-muted">系统版本</dt><dd class="mt-1">{{detail.version||'未记录'}}</dd></div><div><dt class="text-muted">最近校验</dt><dd class="mt-1">{{dateTime(detail.verifiedAt)}}</dd></div><div class="sm:col-span-2"><dt class="text-muted">备份编号</dt><dd class="mt-1 break-all">{{detail.id}}</dd></div><div v-if="detail.sha256" class="sm:col-span-2"><dt class="text-muted">SHA-256</dt><dd class="mt-1 break-all font-mono text-xs">{{detail.sha256}}</dd></div><div v-if="detail.taskId" class="sm:col-span-2"><dt class="text-muted">关联更新任务</dt><dd class="mt-1 break-all text-xs">{{detail.taskId}}</dd></div></dl><UAlert v-if="detail.deleteBlocked" :title="detail.deleteBlocked" color="warning"/><UAlert v-if="detail.error" :title="detail.error" color="error"/><p class="border-t border-default pt-4 text-xs leading-6 text-muted">备份独立保留，不随代码更新清理。还原仅支持相同数据库、系统版本及迁移结构；恢复流程引用的备份受保护。</p></div></template><template #footer><ConsoleFormActions class="w-full"><UButton color="neutral" variant="outline" @click="detailOpen=false">关闭</UButton></ConsoleFormActions></template></UModal>
</div></AdminConsole></template>
